import{EXTRA_CONDITIONS,preventiveStep}from './clinical-extra.js';
import{mix}from './world.js';import{clinicalAccess,ensureHuman,initPeopleWorld,clinicVisit}from './people-world.js';
export const CLINICAL_SOURCE={id:'acvs-patella',url:'https://www.acvs.org/small-animal/patellar-luxations/',retrieved:'2026-10-17',scope:'개 · 증상·진찰·보존적 관리 또는 수술·수 주 안정과 재검의 구조 참고',limitations:'게임의 발생률·등급 배정·발견 지연·치료 가능성·회복 일수는 임상 통계로 보정하지 않은 설정'};
export const CONDITIONS={patella:{label:'슬개골 불안정',min:180,base:.000022,source:'acvs-patella',symptom:'걷다가 한쪽 뒷다리를 몇 걸음 들었다. 다시 딛기도 하지만 뛰려다 멈추고 몸을 낮춘다.',diagnosis:'수의사가 걸음과 무릎을 살핀다. 슬개골 탈구가 확인되어 통증과 보행 상태에 맞춘 관리가 필요해졌다.',recovery:42},ear:{label:'귀 염증',min:150,base:.000018,symptom:'한쪽 귀를 자주 긁고 고개를 턴다. 평소 쓰다듬던 손이 귀에 닿자 몸을 돌린다.',diagnosis:'진료실에서 귀 안쪽을 검사하고 염증에 대한 치료가 시작됐다.',recovery:18},skin:{label:'피부 질환',min:150,base:.000016,symptom:'같은 곳을 핥고 긁는 시간이 늘었다. 잠들었다가도 불편해 자세를 바꾼다.',diagnosis:'피부와 털을 살핀 뒤 원인을 확인하는 검사와 관리를 시작했다.',recovery:24},dental:{label:'치아·잇몸 질환',min:730,base:.000018,symptom:'딱딱한 먹이를 먹다가 내려놓는다. 입 한쪽을 덜 쓰고 천천히 씹는다.',diagnosis:'수의사가 입 안을 검사했다. 치아와 잇몸 상태에 맞춘 처치와 먹이 관리가 필요하다.',recovery:21},joint:{label:'노년 관절 통증',min:2920,base:.000045,symptom:'잠자리에서 일어날 때 다리가 뻣뻣하다. 익숙한 산책길에서도 보폭이 짧아졌다.',diagnosis:'진료실에서 관절과 걸음을 검사한다. 통증을 줄이고 활동과 잠자리를 바꾸는 관리가 시작된다.',recovery:35}};
Object.assign(CONDITIONS,EXTRA_CONDITIONS);
export function initClinical(s){s.clinical??={version:1,active:null,history:[],conditions:{},nextCheck:s.day+60+mix(s.seed,951)%120,preventionDone:false,mobility:100};s.susceptibility??={patella:mix(s.seed,952)%100,skin:mix(s.seed,953)%100};}
const clamp=n=>Math.max(0,Math.min(100,n));
export function startClinical(s,kind,log,{grade=null}={}){initClinical(s);const spec=CONDITIONS[kind];if(!spec||s.clinical.active||s.day<spec.min)return false;const c={id:`clinical:${kind}:${s.day}`,kind,start:s.day,stage:'symptoms',next:s.day+3,actor:s.caregiverId,area:s.areaId,grade:grade??1+mix(s.seed+s.day,955)%4,pain:25,signal:false,diagnosed:false,treatment:null};s.clinical.active=c;s.clinical.mobility=['patella','joint','fracture'].includes(kind)?65:90;log(s,'clinical-symptom',spec.symptom);s.log.at(-1).storyId=c.id;return true;}
export function clinicalChoice(s,p,id,{log}){const c=s.clinical?.active;if(!c||p.id!=='pain-response')return false;c.signal=id==='signal';if(id==='rest')s.needs.fatigue=clamp(s.needs.fatigue-4);log(s,'clinical-response',id==='signal'?'몇 걸음 움직이다가 멈춰 사람 쪽을 본다. 평소와 다른 걸음과 작은 소리가 남는다.':id==='rest'?'움직임을 줄이고 낮은 잠자리에 몸을 눕힌다. 몸이 덜 불편한 자세를 찾는다.':'뛰는 대신 천천히 발을 옮긴다. 불편해지면 멈추고 잠깐 쉰다.');s.log.at(-1).storyId=c.id;return true;}
export function clinicalStep(s,{log,decision}){initClinical(s);initPeopleWorld(s);const med=s.clinical,c=med.active;const emit=(id,text,arc=c)=>{if(['clinical-detected','clinical-diagnosis','surgery-performed','clinical-rehabilitation'].includes(id))clinicVisit(s,id);log(s,id,text);if(arc)s.log.at(-1).storyId=arc.id};
if(!c){const access=clinicalAccess(s);const preventive=preventiveStep(s,{log},access);if(preventive){clinicVisit(s,'preventive');return true;}
if(s.medical.episode||s.story.lost||s.day<150)return false;for(const[k,spec]of Object.entries(CONDITIONS)){if(s.day<spec.min||(spec.eligible&&!spec.eligible(s))||(med.conditions[k]&&(!['ear','skin','joint','chronic'].includes(k)||s.day<(med.conditions[k].nextFlare??Infinity)))||s.day%7!==0)continue;const susceptibility=k==='patella'?(s.appearance.adultKg<10?2:1)*(1+s.susceptibility.patella/100):1;const hazard=1-Math.pow(1-spec.base*susceptibility,7);if(mix(s.seed+s.day,970+Object.keys(CONDITIONS).indexOf(k)) /4294967296<hazard){startClinical(s,k,log);return true}}return false}
const spec=CONDITIONS[c.kind],elapsed=s.day-c.start;if(!clinicalAccess(s).available&&elapsed>30){c.pain=Math.min(70,c.pain+.08);med.mobility=Math.min(med.mobility,c.kind==='patella'||c.kind==='joint'?60:90);}if(elapsed===1&&!s.pending&&!s.medical.episode)decision(s,'pain-response',spec.symptom+' 가까운 자리에서 몸을 쉬거나 돌봄의 기척을 찾을 수 있다.',s.home==='street'?[['rest','낮은 자리에서 몸을 쉰다'],['slow','뛰지 않고 천천히 움직인다']]:[['signal','사람 앞에서 움직이다 멈춰 선다'],['rest','편한 자리에서 쉬려 한다'],['slow','움직임을 줄여 천천히 걷는다']]);
if(s.day<c.next)return ['treatment','recovery','rehabilitation'].includes(c.stage);const access=clinicalAccess(s);if(c.stage==='symptoms'){const h=access.human,detected=access.available&&(c.signal||!h||h.time+h.knowledge>=75||elapsed>=14);if(!detected){c.next=s.day+7;if(elapsed===3)emit('clinical-waiting','불편한 움직임이 이어지지만 아직 진료로 연결되지 않았다. 덜 움직이고 쉬는 자리를 찾는다.');return true}c.stage='diagnosis';c.next=s.day+2;c.detectedBy=h?.id||null;emit('clinical-detected','돌보는 사람이 평소와 다른 움직임을 알아챘다. 며칠 동안의 변화를 기록하고 병원에서 상태를 확인한다.');return true}
if(c.stage==='diagnosis'){if(!access.available){c.stage='symptoms';c.next=s.day+7;return true}c.diagnosed=true;med.conditions[c.kind]={...med.conditions[c.kind],diagnosed:true,grade:c.grade,day:s.day,source:spec.source||'authored'};emit('clinical-diagnosis',spec.diagnosis);c.surgeryIndicated=(c.kind==='patella'&&c.grade>=2||c.kind==='fracture'&&c.grade>=3)&&c.pain>=25;const surgical=c.surgeryIndicated&&access.human?.money>=40&&!s.reproduction.pregnancy&&s.health>=55;c.treatment=surgical?'surgery':'conservative';c.stage='treatment';c.next=s.day+(surgical?5:2);ensureHuman(s,'vet-'+s.country.id,'vet').decisions.push({day:s.day,kind:c.kind,treatment:c.treatment});emit('clinical-plan',surgical?'수의사가 보행과 통증, 전신 상태를 살핀 뒤 수술을 권했다. 돌보는 사람이 일정과 비용, 회복 공간을 마련한다.':c.surgeryIndicated?'수술의 필요성도 검토했지만 지금은 비용이나 전신 상태 때문에 바로 진행하기 어렵다. 우선 불편을 줄이는 관리를 하며 재평가 일정을 잡는다.':'증상과 전신 상태를 살핀 뒤 보존적 관리와 경과 관찰을 시작한다. 활동과 먹이, 쉬는 자리를 조절하고 필요한 재검을 받는다.');return true}
if(c.stage==='treatment'){if(!access.available){c.next=s.day+7;return true}if(c.treatment==='surgery'&&(s.medical.episode||s.reproduction.pregnancy||s.health<55)){c.next=s.day+7;emit('clinical-delayed','전신 상태를 먼저 돌봐야 해 예정된 수술을 미뤘다. 통증을 줄이며 상태를 다시 살핀다.');return true}c.stage='recovery';c.next=s.day+Math.floor(spec.recovery/2);c.treatedAt=s.day;s.needs.fatigue=clamp(s.needs.fatigue+8);emit(c.treatment==='surgery'?'surgery-performed':'conservative-care',c.treatment==='surgery'?c.kind==='fracture'?'병원에서 골절 부위를 고정하는 수술을 받았다. 돌아온 뒤에는 움직임을 제한하고 상처와 고정 부위의 상태를 재검에서 확인한다.':'병원에서 슬개골 교정 수술을 받았다. 돌아온 뒤에는 낮은 잠자리에서 쉬고, 뛰거나 높은 곳에 오르는 활동을 줄인다.':c.kind==='fracture'?'수의사가 골절 형태를 확인한 뒤 외부 고정과 안정으로 관리한다. 사람은 움직임을 제한하고 고정 부위를 정기적으로 확인받는다.':'사람이 먹이와 활동, 쉬는 자리를 조절한다. 수의사가 정한 관리에 따라 불편한 부분을 돌보고 짧게 움직인다.');return true}
if(c.stage==='recovery'){c.stage='rehabilitation';c.next=c.treatedAt+spec.recovery;emit('clinical-rehabilitation',c.treatment==='surgery'?'재검에서 다리의 회복 상태를 살폈다. 사람과 짧고 느린 걸음부터 다시 시작하고, 무리한 달리기는 피한다.':'불편함이 줄어드는지 재검에서 살핀다. 짧게 걷고 쉬는 생활을 이어가며 다시 먹고 움직이는 양을 확인한다.');return true}
if(c.stage==='rehabilitation'){c.stage='managed';c.end=s.day;c.residual=['patella','joint','chronic'].includes(c.kind)&&c.grade>=3;med.mobility=c.residual?80:95;med.history.push({...c});med.conditions[c.kind].managed=true;med.conditions[c.kind].mobility=med.mobility;med.mobility=Math.min(...Object.values(med.conditions).map(x=>x.mobility??100));med.conditions[c.kind].nextFlare=s.day+240+mix(s.seed+s.day,978)%300;emit('clinical-managed',!['patella','joint','fracture'].includes(c.kind)?'먹고 쉬는 모습이 안정됐다. 불편했던 부분의 변화는 기록으로 남기고, 다시 증상이 나타나면 진료에서 확인하기로 한다.':c.residual?'통증은 줄었지만 예전처럼 오래 뛰지는 않는다. 낮은 잠자리와 짧은 산책을 유지하며 정기적으로 상태를 살핀다.':'편하게 발을 딛고 먹는 시간이 늘었다. 무리하지 않는 활동으로 돌아가고, 같은 불편이 생기는지 계속 살핀다.');med.active=null;return true}return false;}
export function validateClinical(s){const c=s.clinical;if(!c)return;if(!Array.isArray(c.history)||!c.conditions||!Number.isFinite(c.mobility)||c.active&&(!CONDITIONS[c.active.kind]||!Number.isInteger(c.active.start)||!['symptoms','diagnosis','treatment','recovery','rehabilitation'].includes(c.active.stage)))throw Error('손상된 진료 기록');}
